namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = ""; // e.g. "CS", "MATH"
    public string Description { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string CourseCode { get; set; } = ""; // e.g. "CS 101"
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = ""; // e.g. "MWF 10:00–10:50 AM"
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "The science of numbers, quantities, and shapes." },
            new() { Id = 3, Name = "English", Code = "ENG", Description = "Study of literature, writing, and the English language." },
            new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilizations." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Programming", CourseCode = "CS 101", Description = "Learn the fundamentals of programming using Python. Topics include variables, control structures, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has over 15 years of experience teaching introductory computer science and has published research on CS education pedagogy.", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", CourseCode = "CS 201", Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and algorithm design techniques such as divide and conquer, dynamic programming, and greedy algorithms.", Credits = 4, Schedule = "TTh 10:30–11:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Marcus Rivera", InstructorBio = "Dr. Rivera specializes in algorithm optimization and competitive programming. He holds a PhD from MIT." },
            new() { Id = 3, Title = "Database Systems", CourseCode = "CS 310", Description = "Introduction to database design, SQL, normalization, transaction processing, and modern NoSQL systems.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Sarah Kim", InstructorBio = "Dr. Kim worked as a database architect at Oracle before joining academia. She focuses on distributed database systems." },
            new() { Id = 4, Title = "Operating Systems", CourseCode = "CS 350", Description = "Concepts of operating system design including process management, memory management, file systems, and concurrency.", Credits = 4, Schedule = "TTh 2:00–3:20 PM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has over 15 years of experience teaching introductory computer science and has published research on CS education pedagogy." },

            // Mathematics
            new() { Id = 5, Title = "Calculus I", CourseCode = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. James Thornton", InstructorBio = "Dr. Thornton is an award-winning mathematics educator with a passion for making calculus accessible to all students.", IsFeatured = true },
            new() { Id = 6, Title = "Linear Algebra", CourseCode = "MATH 220", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "TTh 9:00–10:20 AM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Priya Patel", InstructorBio = "Dr. Patel's research focuses on applied linear algebra and numerical methods. She has authored two textbooks on the subject." },
            new() { Id = 7, Title = "Probability and Statistics", CourseCode = "MATH 340", Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian methods.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. James Thornton", InstructorBio = "Dr. Thornton is an award-winning mathematics educator with a passion for making calculus accessible to all students." },

            // English
            new() { Id = 8, Title = "College Writing", CourseCode = "ENG 101", Description = "Develop essential writing skills including argumentation, research methods, and academic prose. Emphasis on clarity and critical thinking.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", DepartmentId = 3, DepartmentName = "English", InstructorName = "Prof. Eleanor Vance", InstructorBio = "Prof. Vance is a published novelist and essayist who brings creative energy to academic writing instruction.", IsFeatured = true },
            new() { Id = 9, Title = "American Literature", CourseCode = "ENG 250", Description = "Survey of American literary works from the colonial period to the present, including poetry, fiction, and non-fiction.", Credits = 3, Schedule = "TTh 1:00–2:20 PM", DepartmentId = 3, DepartmentName = "English", InstructorName = "Dr. Robert Hayes", InstructorBio = "Dr. Hayes is a Fulbright scholar specializing in 20th-century American fiction and the Harlem Renaissance." },
            new() { Id = 10, Title = "Creative Writing Workshop", CourseCode = "ENG 315", Description = "Workshop-based course in fiction and poetry writing. Students produce original work and participate in peer review.", Credits = 3, Schedule = "W 3:00–5:50 PM", DepartmentId = 3, DepartmentName = "English", InstructorName = "Prof. Eleanor Vance", InstructorBio = "Prof. Vance is a published novelist and essayist who brings creative energy to academic writing instruction." },
