@page "/courses"
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-5">
        <input type="text" class="form-control" name="search" value="@Search" placeholder="Search courses..." />
    </div>
    <div class="col-md-4">
        <select class="form-select" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var results = CatalogService.SearchCourses(Search, DepartmentId);
}

<p class="text-muted">Showing @results.Count course(s)</p>

@if (results.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in results)
            {
                <tr>
                    <td>@course.CourseCode</td>
                    <td>@course.Title</td>
                    <td>@course.DepartmentName</td>
                    <td>@course.Credits</td>
                    <td><a href="courses/@course.Id">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/enroll"
@using System.ComponentModel.DataAnnotations
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject EnrollmentService EnrollmentService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Your enrollment request has been submitted successfully!</h4>
        <p><strong>Student:</strong> @Model.StudentName (@Model.StudentId)</p>
        <p><strong>Course:</strong> @(CatalogService.GetCourse(Model.CourseId)?.CourseCode) &mdash; @(CatalogService.GetCourse(Model.CourseId)?.Title)</p>
    </div>
    <a href="courses" class="btn btn-primary">Back to Course Catalog</a>
}
else
{
    <form method="post">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Student Name</label>
            <input type="text" class="form-control @(_errors.ContainsKey(nameof(Model.StudentName)) ? "is-invalid" : "")"
                   id="studentName" name="Model.StudentName" value="@Model.StudentName" />
            @if (_errors.ContainsKey(nameof(Model.StudentName)))
            {
                <div class="invalid-feedback">@_errors[nameof(Model.StudentName)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" class="form-control @(_errors.ContainsKey(nameof(Model.StudentId)) ? "is-invalid" : "")"
                   id="studentId" name="Model.StudentId" value="@Model.StudentId" />
            @if (_errors.ContainsKey(nameof(Model.StudentId)))
            {
                <div class="invalid-feedback">@_errors[nameof(Model.StudentId)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select class="form-select @(_errors.ContainsKey(nameof(Model.CourseId)) ? "is-invalid" : "")"
                    id="courseId" name="Model.CourseId">
                <option value="0">-- Select a Course --</option>
                @foreach (var course in CatalogService.GetAllCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.CourseCode - @course.Title</option>
                }
            </select>
            @if (_errors.ContainsKey(nameof(Model.CourseId)))
            {
                <div class="invalid-feedback">@_errors[nameof(Model.CourseId)]</div>
            }
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        <a href="courses" class="btn btn-outline-secondary ms-2">Back to Course Catalog</a>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool _submitted;
    private Dictionary<string, string> _errors = new();

    [CascadingParameter]
    public HttpContext? HttpContext { get; set; }

    protected override void OnInitialized()
    {
        if (HttpContext?.Request.Method == "GET" && CourseId.HasValue && CourseId.Value > 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpContext?.Request.Method != "POST")
            return;

        _errors.Clear();
        var validationResults = new List<ValidationResult>();
        var context = new ValidationContext(Model);
        if (!Validator.TryValidateObject(Model, context, validationResults, true))
        {
            foreach (var result in validationResults)
            {
                foreach (var memberName in result.MemberNames)
                {
                    _errors[memberName] = result.ErrorMessage ?? "Invalid value.";
                }
            }
            return;
        }

        EnrollmentService.SubmitRequest(Model);
        _submitted = true;
    }
}

